<!doctype html>
<html lang="fa" dir="rtl">
<head>
    <meta charset="utf-8">
    <meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover">
    <title>صفحه پیدا نشد | صابخونه</title>
    <meta name="robots" content="noindex,nofollow">
    <meta name="theme-color" content="#04121b">
    <link rel="icon" href="/favicon.ico" sizes="any">
    <link rel="apple-touch-icon" href="/pwa/apple-touch-icon.png">
    <link rel="stylesheet" href="{{ asset('css/fonts.css') }}">
    <style>
        *{box-sizing:border-box}
        html,body{height:100%}
        body{margin:0;font-family:'Vazirmatn',system-ui,sans-serif;color:#fff;overflow-x:hidden;background:radial-gradient(55% 70% at 88% -5%,rgba(34,197,170,.38),transparent 62%),radial-gradient(45% 55% at 0% 105%,rgba(240,185,90,.2),transparent 62%),linear-gradient(160deg,#04121b,#0a2a3a 58%,#06383e);background-attachment:fixed}
        body:before{content:"";position:fixed;inset:0;pointer-events:none;background-image:linear-gradient(rgba(255,255,255,.06) 1px,transparent 1px),linear-gradient(90deg,rgba(255,255,255,.06) 1px,transparent 1px);background-size:52px 52px;-webkit-mask-image:radial-gradient(70% 75% at 50% 40%,#000,transparent);mask-image:radial-gradient(70% 75% at 50% 40%,#000,transparent)}
        .dust{position:fixed;inset:0;pointer-events:none;opacity:.8;animation:dust 14s ease-in-out infinite alternate;background:radial-gradient(2px 2px at 8% 22%,#fff,transparent),radial-gradient(1.6px 1.6px at 18% 68%,#8ff0d8,transparent),radial-gradient(2.4px 2.4px at 31% 14%,#fff,transparent),radial-gradient(1.6px 1.6px at 44% 82%,#f6c874,transparent),radial-gradient(2px 2px at 57% 30%,#8ff0d8,transparent),radial-gradient(1.6px 1.6px at 66% 72%,#fff,transparent),radial-gradient(2.4px 2.4px at 78% 18%,#f6c874,transparent),radial-gradient(2px 2px at 88% 60%,#fff,transparent),radial-gradient(1.6px 1.6px at 94% 86%,#8ff0d8,transparent),radial-gradient(2px 2px at 12% 90%,#fff,transparent)}
        .wrap{position:relative;z-index:1;min-height:100%;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:0;padding:28px 20px 40px;text-align:center}
        .brand{position:absolute;top:22px;inset-inline:0;display:flex;justify-content:center}
        .brand a{display:inline-flex;align-items:center;gap:11px;color:#fff;text-decoration:none;font-weight:800;font-size:1.15rem}
        .brand span{width:42px;height:42px;display:grid;place-items:center;padding:5px;border-radius:14px;background:#fff;box-shadow:0 10px 26px rgba(34,197,170,.38)}
        .brand img{display:block;width:100%;height:100%;object-fit:contain}
        .lift{position:relative;width:min(320px,86vw);padding:20px 20px 22px;margin-top:62px;border-radius:30px;background:linear-gradient(160deg,rgba(255,255,255,.14),rgba(255,255,255,.05));border:1px solid rgba(143,240,216,.28);box-shadow:0 40px 90px rgba(0,0,0,.45),0 0 90px rgba(34,197,170,.25),inset 0 1px 0 rgba(255,255,255,.14);backdrop-filter:blur(14px);animation:flt 7s ease-in-out infinite}
        .lift:before{content:"";position:absolute;top:-1px;left:22%;right:22%;height:3px;border-radius:3px;background:linear-gradient(90deg,transparent,#8ff0d8,transparent)}
        .lcd{direction:ltr;padding:12px 8px 6px;border-radius:20px;background:#021017;border:1px solid rgba(143,240,216,.22);box-shadow:inset 0 0 40px rgba(0,0,0,.7)}
        .lcd small{display:block;font-size:.72rem;letter-spacing:.14em;color:rgba(143,240,216,.6);font-weight:700}
        .lcd b{display:block;font-size:clamp(4.4rem,18vw,6.4rem);line-height:1.15;font-weight:900;letter-spacing:.04em;background:linear-gradient(180deg,#d8fff6,#8ff0d8 45%,#22c5aa);-webkit-background-clip:text;background-clip:text;-webkit-text-fill-color:transparent;filter:drop-shadow(0 0 18px rgba(34,197,170,.65));animation:blink 4s infinite}
        .arrows{display:flex;justify-content:center;gap:10px;margin-top:14px}
        .arrows i{width:40px;height:40px;display:grid;place-items:center;border-radius:50%;font-style:normal;font-size:1rem;color:rgba(255,255,255,.55);background:rgba(255,255,255,.07);border:1px solid rgba(255,255,255,.16)}
        .arrows i.on{color:#3a2600;background:linear-gradient(145deg,#f6c874,#e0993a);border-color:transparent;box-shadow:0 0 22px rgba(240,185,90,.6);animation:pulse 2s infinite}
        h1{margin:34px 0 10px;font-size:clamp(1.55rem,5vw,2.4rem);line-height:1.6;font-weight:900}
        h1 em{font-style:normal;background:linear-gradient(100deg,#7af2d9,#22c5aa,#f6c874,#22c5aa,#7af2d9);background-size:220% auto;-webkit-background-clip:text;background-clip:text;-webkit-text-fill-color:transparent;animation:gshift 7s linear infinite}
        p{margin:0 0 28px;max-width:520px;color:#bcd5d9;line-height:2;font-size:1rem}
        .acts{display:flex;flex-wrap:wrap;gap:12px;justify-content:center}
        .btn{display:inline-flex;align-items:center;gap:8px;padding:13px 24px;border-radius:15px;font:inherit;font-weight:800;font-size:.95rem;text-decoration:none;cursor:pointer;border:1px solid transparent;transition:transform .2s,box-shadow .2s,background .2s}
        .btn-p{position:relative;overflow:hidden;color:#fff;background:linear-gradient(135deg,#25cdb1,#087f78);box-shadow:0 14px 30px rgba(19,168,149,.45),inset 0 1px 0 rgba(255,255,255,.35)}
        .btn-p:after{content:"";position:absolute;top:0;bottom:0;width:55%;left:-90%;background:linear-gradient(100deg,transparent,rgba(255,255,255,.5),transparent);transform:skewX(-20deg);animation:shine 4.5s ease-in-out infinite}
        .btn-g{color:#fff;background:rgba(255,255,255,.08);border-color:rgba(255,255,255,.26);backdrop-filter:blur(8px)}
        .btn:hover{transform:translateY(-3px)}.btn-g:hover{background:rgba(255,255,255,.16)}
        .btn:focus-visible{outline:2px solid #8ff0d8;outline-offset:3px}
        .code{margin-top:30px;font-size:.78rem;color:rgba(188,213,217,.6)}
        @keyframes flt{0%,100%{transform:translateY(0)}50%{transform:translateY(-12px)}}
        @keyframes blink{0%,92%,100%{opacity:1}94%{opacity:.55}96%{opacity:1}98%{opacity:.7}}
        @keyframes pulse{0%{box-shadow:0 0 0 0 rgba(246,200,116,.6)}70%,100%{box-shadow:0 0 0 12px rgba(246,200,116,0)}}
        @keyframes gshift{to{background-position:220% center}}
        @keyframes shine{0%,55%{left:-90%}100%{left:150%}}
        @keyframes dust{from{transform:translateY(0)}to{transform:translateY(-18px)}}
        @keyframes rise{from{opacity:0;transform:translateY(24px)}}
        .lift{animation:flt 7s ease-in-out infinite,rise .8s cubic-bezier(.2,.8,.2,1) backwards}
        h1{animation:rise .8s .15s cubic-bezier(.2,.8,.2,1) backwards}p{animation:rise .8s .25s cubic-bezier(.2,.8,.2,1) backwards}.acts{animation:rise .8s .35s cubic-bezier(.2,.8,.2,1) backwards}
        @media(max-width:520px){.btn{width:100%;justify-content:center}.acts{width:100%}}
        @media(prefers-reduced-motion:reduce){*,*:before,*:after{animation:none!important;transition:none!important}}
    </style>
</head>
<body>
    <div class="dust" aria-hidden="true"></div>
    <main class="wrap">
        <div class="brand"><a href="{{ url('/') }}"><span><img src="{{ asset('images/sabkhoneh-mark.png') }}" alt="" width="40" height="40"></span>صابخونه</a></div>

        <div class="lift" aria-hidden="true">
            <div class="lcd"><small>FLOOR</small><b>404</b></div>
            <div class="arrows"><i>▲</i><i class="on">▼</i></div>
        </div>

        <h1>این <em>طبقه</em> در ساختمان ما وجود ندارد</h1>
        <p>صفحه‌ای که دنبالش بودید پیدا نشد. ممکن است آدرس را اشتباه وارد کرده باشید یا صفحه جابه‌جا شده باشد. با دکمه‌های زیر به مسیر درست برگردید.</p>

        <div class="acts">
            <a class="btn btn-p" href="{{ url('/') }}">بازگشت به صفحه اصلی <span aria-hidden="true">←</span></a>
            <a class="btn btn-g" href="{{ url('/articles') }}">مطالب و راهنماها</a>
            <button class="btn btn-g" type="button" id="back">صفحه قبل</button>
        </div>
        <div class="code">کد خطا: ۴۰۴</div>
    </main>
    <script>(function(){var b=document.getElementById('back');if(!b)return;b.addEventListener('click',function(){if(history.length>1){history.back()}else{location.href='/'}})})();</script>
</body>
</html>
